const body = $json.body || $json;
const request = body.request || body;
const forms = Array.isArray(request.forms) ? request.forms : [];
return forms
  .filter(form => form.platform === 'contact_form' || form.metadata?.workflow_type === 'contact_form_outreach')
  .map(form => ({ json: {
    client_id: request.client_id || form.client_id || 'unknown',
    request_id: request.request_id || null,
    autopost_form_id: form.autopost_form_id,
    business_name: form.metadata?.business_name || '',
    contact_form_url: form.metadata?.contact_form_url || form.source_url || '',
    website_url: form.metadata?.website_url || '',
    edited_message: form.edited_message || form.draft_message || '',
    approval_decision: form.approval_decision || '',
    guardian_status: form.guardian_status || 'VALIDATION_HUMAINE_OBLIGATOIRE',
    score: form.score || 0,
    metadata: form.metadata || {}
  }}));

return $input.all().map(item => {
  const j = item.json;
  const errors = [];
  if (!j.contact_form_url) errors.push('missing_contact_form_url');
  if (!j.edited_message) errors.push('missing_message');
  if (j.approval_decision !== 'approve_for_manual_post') errors.push('human_approval_missing');
  if (j.guardian_status === 'BLOQUE') errors.push('guardian_blocked');
  const status = errors.length ? 'manual_review' : 'queued_for_worker';
  return { json: { ...j, status, errors, worker_allowed: errors.length === 0 } };
});
